/* This is a placeholder - Please download the actual FullCalendar JS from the CDN */

// Basic fallback for FullCalendar
if (typeof FullCalendar === 'undefined') {
    window.FullCalendar = {
        Calendar: function(el, options) {
            return {
                render: function() {
                    el.innerHTML = '<div style="padding:2rem;text-align:center;border:1px solid #ddd;border-radius:8px;background:#f8f9fa;"><h5>FullCalendar Library Not Loaded</h5><p>Please download FullCalendar from <a href="https://fullcalendar.io/" target="_blank">https://fullcalendar.io/</a></p></div>';
                },
                today: function() {},
                prev: function() {},
                next: function() {}
            };
        }
    };
}
